package mz.bam.seeky.android;
import android.database.*;import android.database.sqlite.*;import java.io.*;import java.util.*;import java.util.function.BooleanSupplier;import java.util.regex.*;
/** Reads a private copy of a MyBible module. No imported SQL is executed. */
final class BibleMyBible {
 static final String[] CODES={"GEN","EXO","LEV","NUM","DEU","JOS","JDG","RUT","1SA","2SA","1KI","2KI","1CH","2CH","EZR","NEH","TOB","JDT","EST","1MA","2MA","JOB","PSA","PRO","ECC","SNG","WIS","SIR","ISA","JER","LAM","BAR","EZK","DAN","HOS","JOL","AMO","OBA","JON","MIC","NAM","HAB","ZEP","HAG","ZEC","MAL","MAT","MRK","LUK","JHN","ACT","ROM","1CO","2CO","GAL","EPH","PHP","COL","1TH","2TH","1TI","2TI","TIT","PHM","HEB","JAS","1PE","2PE","1JN","2JN","3JN","JUD","REV"};
 static boolean table(SQLiteDatabase db,String name){try(Cursor c=db.rawQuery("SELECT sql FROM sqlite_master WHERE type='table' AND name=?",new String[]{name})){return c.moveToFirst()&&c.getString(0)!=null&&!c.getString(0).toUpperCase(Locale.ROOT).contains("VIRTUAL TABLE");}}
 static Set<String> columns(SQLiteDatabase db,String table){Set<String> fields=new HashSet<>();try(Cursor c=db.rawQuery("PRAGMA table_info(\""+table+"\")",null)){while(c.moveToNext())fields.add(c.getString(c.getColumnIndexOrThrow("name")).toLowerCase(Locale.ROOT));}return fields;}
 static String standard(int number){return number%10==0&&number>=10&&number<=CODES.length*10?BibleText.code(CODES[number/10-1]):"";}
 static String clean(String raw)throws IOException{if(raw==null||raw.length()>65536)throw new IOException("Versículo MyBible vazio ou demasiado longo.");String value=raw.replaceAll("(?is)<(S|f|n|script|style)\\b[^>]*>.*?</\\1\\s*>","").replaceAll("(?is)<(?:br|pb)\\s*/?>"," ").replaceAll("(?s)<[^>]*>","");Matcher entities=Pattern.compile("&(#x[0-9a-fA-F]+|#[0-9]+|[A-Za-z]+);").matcher(value);StringBuffer out=new StringBuffer();while(entities.find()){String code=entities.group(1),replacement=null;try{if(code.startsWith("#")){int n=Integer.parseInt(code.substring(code.startsWith("#x")?2:1),code.startsWith("#x")?16:10);if(Character.isValidCodePoint(n)&&n>0&&(n<0xd800||n>0xdfff))replacement=new String(Character.toChars(n));}}catch(Exception ignored){}if(replacement==null){String[] keys={"amp","lt","gt","quot","apos","nbsp","hellip","ndash","mdash","lsquo","rsquo","ldquo","rdquo","laquo","raquo"};String[] texts={"&","<",">","\"","'"," ","…","–","—","‘","’","“","”","«","»"};for(int i=0;i<keys.length;i++)if(keys[i].equals(code))replacement=texts[i];}entities.appendReplacement(out,Matcher.quoteReplacement(replacement==null?entities.group():replacement));}entities.appendTail(out);return out.toString().replaceAll("[\\s\\p{Zs}]+"," ").trim();}
 static int read(File file,BibleText.Sink sink,BooleanSupplier stop,Runnable pulse)throws Exception{try(InputStream in=new FileInputStream(file)){byte[] head=new byte[16];if(in.read(head)!=16||!Arrays.equals(head,"SQLite format 3\000".getBytes("US-ASCII")))throw new IOException("O ficheiro não é uma base de dados SQLite legível.");}
  try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS)){
   if(!table(db,"verses")||!columns(db,"verses").containsAll(Arrays.asList("book_number","chapter","verse","text")))throw new IOException("Este módulo não contém a tabela de versículos MyBible. Ficheiros .search, comentários, dicionários e planos não são Bíblias de texto.");
   Map<Integer,String> names=new HashMap<>();if(table(db,"books")&&columns(db,"books").contains("book_number")){Set<String> fields=columns(db,"books");String longName=fields.contains("long_name")?"long_name":"''",shortName=fields.contains("short_name")?"short_name":"''";try(Cursor c=db.rawQuery("SELECT book_number,"+longName+","+shortName+" FROM books",null)){while(c.moveToNext()){if(stop.getAsBoolean())throw new InterruptedIOException();String name=BibleText.code(clean(c.isNull(1)?"":c.getString(1)));if(name.isEmpty())name=BibleText.code(clean(c.isNull(2)?"":c.getString(2)));if(!name.isEmpty())names.put(c.getInt(0),name);if(names.size()>500)throw new IOException("Módulo com demasiados livros.");}}}
   int count=0;try(Cursor c=db.rawQuery("SELECT book_number,chapter,verse,text FROM verses ORDER BY book_number,chapter,verse",null)){while(c.moveToNext()){if(stop.getAsBoolean())throw new InterruptedIOException("Importação MyBible cancelada.");pulse.run();int number=c.getInt(0),chapter=c.getInt(1),verse=c.getInt(2);if(chapter==0||verse==0)continue;String book=names.getOrDefault(number,standard(number));if(book.isEmpty())throw new IOException("Livro MyBible desconhecido: "+number+". O módulo precisa de nomes de livros reconhecidos.");if(c.getType(3)!=Cursor.FIELD_TYPE_STRING)throw new IOException("O módulo usa versículos comprimidos ou num formato não suportado.");if(count>=200000)throw new IOException("A Bíblia excede 200000 versículos.");if(BibleText.emit(sink,book,chapter,verse,clean(c.getString(3))))count++;}}if(count==0)throw new IOException("O módulo MyBible não contém versículos de texto.");return count;
  }catch(SQLiteException e){throw new IOException("Não foi possível ler o módulo MyBible SQLite3: "+e.getMessage(),e);}
 }
 interface Titles{void title(String book,int chapter,int verse,int order,String text)throws Exception;}
 /** Section titles of a MyBible module: "stories" (inside Bibles), "subheadings" (.subheadings.SQLite3) or "headings". Returns how many. */
 static int titles(File file,Titles sink,BooleanSupplier stop)throws Exception{try(SQLiteDatabase db=SQLiteDatabase.openDatabase(file.getPath(),null,SQLiteDatabase.OPEN_READONLY|SQLiteDatabase.NO_LOCALIZED_COLLATORS)){
   Map<Integer,String> names=new HashMap<>();if(table(db,"books")&&columns(db,"books").contains("book_number")){Set<String> fields=columns(db,"books");String longName=fields.contains("long_name")?"long_name":"''",shortName=fields.contains("short_name")?"short_name":"''";try(Cursor c=db.rawQuery("SELECT book_number,"+longName+","+shortName+" FROM books",null)){while(c.moveToNext()){String name=BibleText.code(clean(c.isNull(1)?"":c.getString(1)));if(name.isEmpty())name=BibleText.code(clean(c.isNull(2)?"":c.getString(2)));if(!name.isEmpty())names.put(c.getInt(0),name);}}}
   String[][] kinds={{"stories","title"},{"subheadings","subheading"},{"headings","heading"},{"subheadings","title"}};
   for(String[] k:kinds){if(!table(db,k[0]))continue;Set<String> cols=columns(db,k[0]);if(!cols.containsAll(Arrays.asList("book_number","chapter","verse",k[1])))continue;String order=cols.contains("order_if_several")?"order_if_several":"0";int count=0;
    try(Cursor c=db.rawQuery("SELECT book_number,chapter,verse,"+order+","+k[1]+" FROM "+k[0]+" ORDER BY book_number,chapter,verse,"+order,null)){while(c.moveToNext()){if(stop.getAsBoolean())throw new InterruptedIOException("Importação cancelada.");String book=names.getOrDefault(c.getInt(0),standard(c.getInt(0)));if(book.isEmpty()||c.getType(4)!=Cursor.FIELD_TYPE_STRING)continue;String text;try{text=clean(c.getString(4));}catch(IOException e){continue;}if(text.isEmpty()||text.length()>400)continue;if(++count>100000)throw new IOException("Demasiados títulos no módulo.");sink.title(book,Math.max(1,c.getInt(1)),Math.max(1,c.getInt(2)),c.getInt(3),text);}}
    if(count>0)return count;}
   return 0;
  }catch(SQLiteException e){throw new IOException("Não foi possível ler o módulo MyBible SQLite3: "+e.getMessage(),e);}
 }
 private BibleMyBible(){}
}
